record.field:
for record in records:
        if record.x_studio_almacen:
                # Obtener las ubicaciones relacionadas con el almacén
                location_ids = env['stock.location'].search([
                ('location_id', 'child_of', [record.x_studio_almacen.view_location_id.id])
                ]).ids
                if location_ids:
                        # Buscar todos los productos, incluidos los kits
                        products = env['product.product'].search([
                        ('location_id', 'in', location_ids)
                        ])
                        # Limpiar los registros existentes en x_studio_inventarios
                        record.x_studio_inventarios.unlink()
                        # Crear nuevos registros con las existencias agrupadas por producto
                        for product in products:
                                product_qty = 0 # Inicializar cantidad del producto
                                if product.bom_ids: # Verificar si el producto tiene una lista de materiales
                                        # Calcular la existencia del kit basándose en sus componentes
                                        quantities = []
                                        for bom_line in product.bom_ids.bom_line_ids:
                                                component_qty = sum(bom_line.product_id.stock_quant_ids.filtered(
                                                        lambda q: q.location_id.id in location_ids).mapped('available_quantity'))
                                                quantities.append(component_qty // bom_line.product_qty if bom_line.product_qty > 0 else 0)
                                        product_qty = min(quantities) if quantities else 0

                                else:
                                        product_qty = sum(product.stock_quant_ids.filtered(
                                        lambda q: q.location_id.id in location_ids).mapped('available_quantity'))
                                        # Solo crear un registro si la cantidad es mayor que cero
                                if product_qty > -1:
                                        env['x_lininvsync'].create({
                                        'x_studio_inventario_por_ubicacin': record.id,
                                        'x_studio_producto': product.id,
                                        'x_name': product.display_name,
                                        'x_studio_stock': product_qty,
                                        })
